import{_ as a,o as n,c as t,a0 as s}from"./chunks/framework.LceoKIk6.js";const h=JSON.parse('{"title":"01 — Project Overview & Architecture","description":"","frontmatter":{},"headers":[],"relativePath":"guide/overview.md","filePath":"guide/overview.md"}'),i={name:"guide/overview.md"};function o(r,e,l,d,p,c){return n(),t("div",null,[...e[0]||(e[0]=[s(`<h1 id="_01-—-project-overview-architecture" tabindex="-1">01 — Project Overview &amp; Architecture <a class="header-anchor" href="#_01-—-project-overview-architecture" aria-label="Permalink to &quot;01 — Project Overview &amp; Architecture&quot;">​</a></h1><h2 id="vision" tabindex="-1">Vision <a class="header-anchor" href="#vision" aria-label="Permalink to &quot;Vision&quot;">​</a></h2><p><strong>sci-notebook</strong> is a framework-agnostic, highly configurable library for creating and visualizing scientific notebooks. It provides a dual-mode editor (raw Markdown / rendered preview), native LaTeX formula support, Mermaid diagrams, embeddable HTML/React/any-framework components, image and table inlining, and an AI-agent connection layer for real-time text predictions — all designed for maximum performance.</p><h2 id="design-principles" tabindex="-1">Design Principles <a class="header-anchor" href="#design-principles" aria-label="Permalink to &quot;Design Principles&quot;">​</a></h2><ul><li><strong>Framework-agnostic core</strong>: The kernel is pure TypeScript with zero framework dependencies. Thin adapter layers expose it to React, Vue, Svelte, Solid, or vanilla JS.</li><li><strong>Plugin-first</strong>: Every non-trivial feature (LaTeX, Mermaid, AI completions, embeds) is a plugin. The core ships with a minimal set; users opt-in to what they need.</li><li><strong>Performance by default</strong>: Virtual rendering for large documents, incremental parsing, lazy plugin loading, and Web Worker offloading where beneficial.</li><li><strong>Serializable state</strong>: The entire notebook is a plain JSON document. No opaque binary blobs. Easy to persist, diff, and version-control.</li><li><strong>Extensible at every layer</strong>: Custom cell types, custom renderers, custom toolbar actions, custom keybindings, custom AI providers.</li></ul><hr><h2 id="high-level-architecture" tabindex="-1">High-Level Architecture <a class="header-anchor" href="#high-level-architecture" aria-label="Permalink to &quot;High-Level Architecture&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>┌─────────────────────────────────────────────────────────┐</span></span>
<span class="line"><span>│                    Framework Adapter                    │</span></span>
<span class="line"><span>│          (React / Vue / Svelte / Vanilla JS)            │</span></span>
<span class="line"><span>├─────────────────────────────────────────────────────────┤</span></span>
<span class="line"><span>│                     Toolbar / UI Shell                  │</span></span>
<span class="line"><span>├──────────┬──────────┬───────────────────────────────────┤</span></span>
<span class="line"><span>│  Editor  │ Preview  │         Side Panels               │</span></span>
<span class="line"><span>│  (Edit)  │ (View)   │   (TOC, Outline, AI Chat)         │</span></span>
<span class="line"><span>├──────────┴──────────┴───────────────────────────────────┤</span></span>
<span class="line"><span>│                   Plugin Manager                        │</span></span>
<span class="line"><span>│  ┌──────┐ ┌────────┐ ┌────────┐ ┌──────┐ ┌───────────┐  │</span></span>
<span class="line"><span>│  │LaTeX │ │Mermaid │ │Embeds  │ │ AI   │ │  Custom   │  │</span></span>
<span class="line"><span>│  └──────┘ └────────┘ └────────┘ └──────┘ └───────────┘  │</span></span>
<span class="line"><span>├─────────────────────────────────────────────────────────┤</span></span>
<span class="line"><span>│                  Rendering Pipeline                     │</span></span>
<span class="line"><span>│         (Markdown Parser → AST → Renderers)             │</span></span>
<span class="line"><span>├─────────────────────────────────────────────────────────┤</span></span>
<span class="line"><span>│                    Editor Engine                        │</span></span>
<span class="line"><span>│       (Cell Manager, Selection, Undo/Redo, Keybindings) │</span></span>
<span class="line"><span>├─────────────────────────────────────────────────────────┤</span></span>
<span class="line"><span>│                    Document Model                       │</span></span>
<span class="line"><span>│            (Notebook → Cells → Content)                 │</span></span>
<span class="line"><span>├─────────────────────────────────────────────────────────┤</span></span>
<span class="line"><span>│                  Event Bus / State                      │</span></span>
<span class="line"><span>│          (Pub-Sub, Immutable Snapshots, History)        │</span></span>
<span class="line"><span>└─────────────────────────────────────────────────────────┘</span></span></code></pre></div><hr><h2 id="package-structure-monorepo" tabindex="-1">Package Structure (Monorepo) <a class="header-anchor" href="#package-structure-monorepo" aria-label="Permalink to &quot;Package Structure (Monorepo)&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>sci-notebook/</span></span>
<span class="line"><span>├── packages/</span></span>
<span class="line"><span>│   ├── core/               # Document model, editor engine, event bus</span></span>
<span class="line"><span>│   ├── renderer/           # Markdown→AST→HTML rendering pipeline</span></span>
<span class="line"><span>│   ├── plugin-latex/       # KaTeX-based LaTeX rendering</span></span>
<span class="line"><span>│   ├── plugin-mermaid/     # Mermaid diagram rendering</span></span>
<span class="line"><span>│   ├── plugin-embeds/      # HTML / framework component embedding</span></span>
<span class="line"><span>│   ├── plugin-ai/          # AI agent connection (completions, rewrites)</span></span>
<span class="line"><span>│   ├── plugin-images/      # Image upload, paste, drag-drop, resize</span></span>
<span class="line"><span>│   ├── plugin-tables/      # Rich table editing inside cells</span></span>
<span class="line"><span>│   ├── react/              # React adapter + hooks</span></span>
<span class="line"><span>│   ├── vue/                # Vue adapter (future)</span></span>
<span class="line"><span>│   ├── svelte/             # Svelte adapter (future)</span></span>
<span class="line"><span>│   └── vanilla/            # Vanilla JS adapter</span></span>
<span class="line"><span>├── docs/                   # This development schema</span></span>
<span class="line"><span>├── examples/</span></span>
<span class="line"><span>│   ├── react-basic/</span></span>
<span class="line"><span>│   ├── react-full/</span></span>
<span class="line"><span>│   └── vanilla/</span></span>
<span class="line"><span>├── tests/</span></span>
<span class="line"><span>│   ├── unit/</span></span>
<span class="line"><span>│   ├── integration/</span></span>
<span class="line"><span>│   └── e2e/</span></span>
<span class="line"><span>├── package.json            # Workspace root</span></span>
<span class="line"><span>├── tsconfig.json</span></span>
<span class="line"><span>├── vitest.config.ts</span></span>
<span class="line"><span>└── README.md</span></span></code></pre></div><hr><h2 id="technology-choices" tabindex="-1">Technology Choices <a class="header-anchor" href="#technology-choices" aria-label="Permalink to &quot;Technology Choices&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Layer</th><th>Technology</th><th>Rationale</th></tr></thead><tbody><tr><td>Language</td><td>TypeScript (strict)</td><td>Type safety, IDE support</td></tr><tr><td>Build</td><td>tsup + Vite</td><td>Fast builds, tree-shaking</td></tr><tr><td>Monorepo</td><td>pnpm workspaces</td><td>Efficient, well-supported</td></tr><tr><td>Markdown Parser</td><td>markdown-it (pluggable)</td><td>Fast, extensible, battle-tested</td></tr><tr><td>LaTeX</td><td>KaTeX</td><td>Fastest LaTeX renderer for the web</td></tr><tr><td>Diagrams</td><td>Mermaid</td><td>De-facto standard for text diagrams</td></tr><tr><td>Testing</td><td>Vitest + Playwright</td><td>Fast unit + real browser e2e</td></tr><tr><td>State</td><td>Custom immutable store</td><td>No framework dependency</td></tr><tr><td>Styling</td><td>CSS variables + BEM</td><td>Framework-agnostic, themeable</td></tr></tbody></table><hr><h2 id="core-concepts" tabindex="-1">Core Concepts <a class="header-anchor" href="#core-concepts" aria-label="Permalink to &quot;Core Concepts&quot;">​</a></h2><h3 id="notebook" tabindex="-1">Notebook <a class="header-anchor" href="#notebook" aria-label="Permalink to &quot;Notebook&quot;">​</a></h3><p>A notebook is a JSON document containing an ordered list of <strong>cells</strong>. Each cell has a <code>type</code>, <code>source</code> (raw content), and optional <code>metadata</code>.</p><h3 id="cell" tabindex="-1">Cell <a class="header-anchor" href="#cell" aria-label="Permalink to &quot;Cell&quot;">​</a></h3><p>The atomic unit. Built-in types: <code>markdown</code>, <code>code</code>, <code>raw</code>. Plugins can register custom types (e.g., <code>latex-block</code>, <code>mermaid</code>, <code>embed</code>, <code>table</code>, <code>image</code>).</p><h3 id="dual-mode" tabindex="-1">Dual Mode <a class="header-anchor" href="#dual-mode" aria-label="Permalink to &quot;Dual Mode&quot;">​</a></h3><ul><li><strong>Edit mode</strong>: Shows raw Markdown source with syntax highlighting. The user types freely.</li><li><strong>View mode</strong>: Renders the Markdown through the rendering pipeline, applying all plugins.</li><li>Per-cell or per-notebook toggle. Clicking a rendered cell switches it to edit mode.</li></ul><h3 id="plugin" tabindex="-1">Plugin <a class="header-anchor" href="#plugin" aria-label="Permalink to &quot;Plugin&quot;">​</a></h3><p>A plugin is an object conforming to <code>SciNotebookPlugin</code> interface. It can:</p><ul><li>Register new cell types</li><li>Hook into the rendering pipeline (AST transforms)</li><li>Add toolbar buttons</li><li>Register keybindings</li><li>Provide AI completion providers</li><li>Inject CSS</li></ul><h3 id="event-bus" tabindex="-1">Event Bus <a class="header-anchor" href="#event-bus" aria-label="Permalink to &quot;Event Bus&quot;">​</a></h3><p>A synchronous pub-sub system. All state mutations emit events. Plugins and adapters subscribe to react. Events are typed and documented.</p><hr><h2 id="non-goals-explicit-exclusions" tabindex="-1">Non-Goals (Explicit Exclusions) <a class="header-anchor" href="#non-goals-explicit-exclusions" aria-label="Permalink to &quot;Non-Goals (Explicit Exclusions)&quot;">​</a></h2><ul><li><strong>Code execution</strong>: This is a <em>document</em> editor, not a Jupyter kernel. Code cells are for display/syntax highlighting only (execution can be added via plugin).</li><li><strong>Collaboration / CRDT</strong>: Real-time multi-user editing is out of scope for v1. The architecture does not prevent it, but it is not a deliverable.</li><li><strong>PDF export</strong>: Can be added as a plugin later. Not in core scope.</li></ul><hr><h2 id="document-index" tabindex="-1">Document Index <a class="header-anchor" href="#document-index" aria-label="Permalink to &quot;Document Index&quot;">​</a></h2><table tabindex="0"><thead><tr><th>#</th><th>File</th><th>Content</th></tr></thead><tbody><tr><td>1</td><td><code>01-overview.md</code></td><td>This file — vision, architecture, packages</td></tr><tr><td>2</td><td><code>02-data-model.md</code></td><td>Notebook/Cell JSON schema, types</td></tr><tr><td>3</td><td><code>03-editor-engine.md</code></td><td>Cell manager, selection, undo/redo, keys</td></tr><tr><td>4</td><td><code>04-rendering-pipeline.md</code></td><td>MD parsing, AST, renderer chain</td></tr><tr><td>5</td><td><code>05-plugin-system.md</code></td><td>Plugin interface, lifecycle, registration</td></tr><tr><td>6</td><td><code>06-latex-mermaid-embeds.md</code></td><td>LaTeX, Mermaid, HTML/component embeds</td></tr><tr><td>7</td><td><code>07-ai-integration.md</code></td><td>Agent protocol, inline completions</td></tr><tr><td>8</td><td><code>08-framework-adapters.md</code></td><td>React/Vue/Svelte/Vanilla adapters, API</td></tr><tr><td>9</td><td><code>09-performance.md</code></td><td>Virtual rendering, lazy loading, workers</td></tr><tr><td>10</td><td><code>10-roadmap.md</code></td><td>Phased development plan, milestones</td></tr></tbody></table>`,33)])])}const g=a(i,[["render",o]]);export{h as __pageData,g as default};
